SELECT EXISTS (
    SELECT 1 FROM performance_cast
    WHERE performance_character_id = #{performanceCharacterId}
)

SELECT EXISTS (
    SELECT 1 FROM performance_cast_history
    WHERE performance_character_id = #{performanceCharacterId}
)

SELECT performance_media_id, performance_project_id, stored_file_id, media_type_code, title, description, alt_text, credit_text, external_url, display_order, is_published FROM performance_media WHERE performance_project_id = #{performanceProjectId}
AND is_published = 1
ORDER BY display_order, performance_media_id

